BEGIN;
SET LOCAL statement_timeout = '15s';
SET LOCAL lock_timeout = '2s';
CREATE TEMP TABLE neg_results (who text, test text, outcome text);
GRANT INSERT ON neg_results TO truenote_app;
-- As the application role: each statement must fail (zero rows targeted).
SET LOCAL ROLE truenote_app;
DO $$
DECLARE
  t text;
  tests text[] := ARRAY[
    'UPDATE security_events SET action = action WHERE false',
    'DELETE FROM security_events WHERE false',
    'TRUNCATE security_events',
    'INSERT INTO security_events (action, outcome, event_hash) SELECT action, outcome, event_hash FROM security_events WHERE false',
    'SELECT 1 FROM schema_migrations LIMIT 0',
    'SELECT 1 FROM siem_delivery_outbox LIMIT 0',
    'SELECT 1 FROM security_control_metadata LIMIT 0',
    'CREATE TABLE public.neg_probe (id int)',
    'CREATE TABLE pgboss.neg_probe (id int)',
    'CREATE TEMP TABLE neg_probe (id int)',
    'CREATE SCHEMA neg_probe',
    'CREATE FUNCTION public.neg_probe() RETURNS int LANGUAGE sql AS ''SELECT 1''',
    'ALTER TABLE users ADD COLUMN neg_probe int',
    'TRUNCATE users',
    'GRANT SELECT ON users TO PUBLIC',
    'SELECT pgboss.delete_queue(''neg-probe-nonexistent'')',
    'ALTER TABLE security_events DISABLE TRIGGER security_events_append_only'
  ];
BEGIN
  FOREACH t IN ARRAY tests LOOP
    BEGIN
      EXECUTE t;
      INSERT INTO neg_results VALUES ('truenote_app', t, 'ALLOWED');
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO neg_results VALUES ('truenote_app', t, 'refused ' || SQLSTATE || ': ' || SQLERRM);
    END;
  END LOOP;
  -- Must succeed: zero-row reads and writes on granted tables.
  FOREACH t IN ARRAY ARRAY[
    'SELECT 1 FROM users LIMIT 0',
    'SELECT 1 FROM security_events LIMIT 0',
    'UPDATE users SET name = name WHERE false',
    'DELETE FROM sessions WHERE false',
    'INSERT INTO error_log SELECT * FROM error_log WHERE false',
    'UPDATE pgboss.queue SET name = name WHERE false',
    'SELECT 1 FROM pgboss.version LIMIT 0',
    'DELETE FROM pgboss.job WHERE false'
  ] LOOP
    BEGIN
      EXECUTE t;
      INSERT INTO neg_results VALUES ('truenote_app', t, 'allowed (expected)');
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO neg_results VALUES ('truenote_app', t, 'FAILED ' || SQLSTATE || ': ' || SQLERRM);
    END;
  END LOOP;
END
$$;
RESET ROLE;
-- As the owner: the append-only triggers must refuse (inside this rolled-back transaction).
DO $$
BEGIN
  BEGIN
    DELETE FROM security_events WHERE sequence = (SELECT min(sequence) FROM security_events);
    INSERT INTO neg_results VALUES ('postgres', 'DELETE oldest security_events row', 'ALLOWED');
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO neg_results VALUES ('postgres', 'DELETE oldest security_events row', 'refused ' || SQLSTATE || ': ' || SQLERRM);
  END;
  BEGIN
    UPDATE security_events SET action = action WHERE sequence = (SELECT min(sequence) FROM security_events);
    INSERT INTO neg_results VALUES ('postgres', 'UPDATE oldest security_events row', 'ALLOWED');
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO neg_results VALUES ('postgres', 'UPDATE oldest security_events row', 'refused ' || SQLSTATE || ': ' || SQLERRM);
  END;
  BEGIN
    TRUNCATE security_events;
    INSERT INTO neg_results VALUES ('postgres', 'TRUNCATE security_events', 'ALLOWED');
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO neg_results VALUES ('postgres', 'TRUNCATE security_events', 'refused ' || SQLSTATE || ': ' || SQLERRM);
  END;
END
$$;
SELECT who || ' | ' || test || ' | ' || outcome FROM neg_results;
ROLLBACK;
